import random
class RandomizedSet:
    def __init__(self):
        self.l = []; self.idx = {}
    def insert(self, v):
        if v in self.idx: return False
        self.idx[v] = len(self.l); self.l.append(v); return True
    def remove(self, v):
        if v not in self.idx: return False
        i = self.idx[v]; last = self.l[-1]
        self.l[i] = last; self.idx[last] = i
        self.l.pop(); del self.idx[v]; return True
    def get_random(self):
        return random.choice(self.l)
